INSERT INTO converted_files (title, description, file_url, file_name, s3_key, size_bytes) VALUES ('Счета от 19.10.26 в загрузку', 'Два счёта ООО «ВГ-ТРЕЙД» (Weissgauff) № 1222 и № 1223 от 20.10.2026 объединены по правилу «Создание файла для OData». Восемь колонок: Артикул (колонка «Код», текстом), Штрихкод (текстом), Наименование (как в счёте), Количество, Цена с НДС, Страна, Номер ГТД, Номер РНПТ (в счетах нет — пусто). Строки идут подряд: сначала счёт 1222 (105 строк, 1 384 602,90 руб.), затем 1223 (109 строк, 1 364 253,40 руб.), порядок как в оригинале, совпадающие товары не схлопнуты. Всего 214 строк, сумма 2 748 856,30 руб. — сходится с итогами счетов до копейки.', '/converted/scheta-ot-19-10-26-v-zagruzku.xlsx', 'Счета от 19.10.26 в загрузку.xlsx', 'converted/scheta-ot-19-10-26-v-zagruzku.xlsx', 14632);